package hu.synostream.android;
import android.app.*;import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.*;import java.io.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class Android050FlowTest {
    final String pkg="hu.synostream.android";Context context;SynoApp app;UiDevice device;android.app.Instrumentation instrumentation;
    void setup(FakeNas nas,List<Library.Card> cards)throws Exception{instrumentation=InstrumentationRegistry.getInstrumentation();context=instrumentation.getTargetContext();app=(SynoApp)context.getApplicationContext();device=UiDevice.getInstance(instrumentation);device.wakeUp();device.executeShellCommand("wm dismiss-keyguard");device.setOrientationNatural();NasClient client=new NasClient(new NasClient.Credentials(nas.address(),"","fixture-user","fixture-password",""));client.connect();instrumentation.runOnMainSync(()->{app.client=client;app.demo=false;app.busy=false;app.downloadBusy=false;app.downloads=null;app.downloadsOpen=false;app.libraryDraft=null;app.epoch++;app.identity="flow-fixture-"+System.nanoTime();app.edits=new LocalEdits("{}");app.page="movies";app.query="";app.libraries=LibraryConfig.migrate(new JSONArray());JSONObject lib=LibraryConfig.defaultLibrary(app.libraries,true);try{LibraryConfig.paths(lib,List.of("/Movies"));}catch(Exception e){throw new RuntimeException(e);}app.selectedLibrary=lib.optString("id");app.automaticLibraries.prepare(app.identity+"#"+app.epoch,List.of(app.selectedLibrary),android.os.SystemClock.elapsedRealtime());app.automaticLibraries.cancel(android.os.SystemClock.elapsedRealtime());app.rawCards=new ArrayList<>(cards);app.cards=new ArrayList<>(cards);});app.store.secret("tmdb_key","");context.startActivity(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));assertTrue(device.wait(Until.hasObject(By.res(pkg+":id/menu_button")),15000));instrumentation.runOnMainSync(()->{app.automaticForeground(false);if(app.automaticScan)app.cancelScan();});}
    void click(String id){assertTrue(id,device.wait(Until.hasObject(By.res(pkg+":id/"+id)),10000));device.findObject(By.res(pkg+":id/"+id)).click();}
    void text(String value){assertTrue(value,device.wait(Until.hasObject(By.text(value)),10000));device.findObject(By.text(value)).click();}
    MainActivity activity(){MainActivity[] result={null};instrumentation.runOnMainSync(()->{try{java.lang.reflect.Field f=SynoApp.class.getDeclaredField("ui");f.setAccessible(true);result[0]=(MainActivity)((java.lang.ref.WeakReference<?>)f.get(app)).get();}catch(Exception e){throw new RuntimeException(e);}});return result[0];}
    void cleanup()throws Exception{if(context!=null){context.stopService(new Intent(context,StreamService.class));context.stopService(new Intent(context,ScanService.class));}if(app!=null){app.downloadsOpen=false;if(app.downloads!=null)app.downloads.close();app.downloads=null;NasClient old=app.client;app.client=null;if(old!=null)old.logout();}if(device!=null){device.wakeUp();device.setOrientationNatural();device.unfreezeRotation();}}
    @Test public void torrentPreviewSelectsNfoExcludesSampleAndStartsOnlyOnConfirmation()throws Exception{try(FakeNas nas=new FakeNas()){try{setup(nas,List.of());click("menu_button");text("Letöltések");assertTrue(device.wait(Until.hasObject(By.text("Fixture torrent")),15000));text("Hozzáadás");assertTrue(device.wait(Until.hasObject(By.clazz("android.widget.EditText")),10000));UiObject2 input=device.findObject(By.clazz("android.widget.EditText"));assertNotNull(input);input.setText("https://example.org/fixture.torrent");text("Hozzáadás");assertTrue(device.wait(Until.hasObject(By.text("release.nfo")),15000));assertEquals(1,nas.prepares);assertEquals("No download before file confirmation",0,nas.starts);assertTrue(device.findObject(By.text("release.nfo")).isChecked());assertFalse(device.findObject(By.text("Sample/clip.mkv")).isChecked());assertTrue(device.takeScreenshot(new File(context.getFilesDir(),"050-torrent-files.png")));text("Kijelölt fájlok letöltése");long end=System.currentTimeMillis()+15000;while((nas.starts==0||app.downloadBusy)&&System.currentTimeMillis()<end)Thread.sleep(50);assertEquals(1,nas.starts);assertTrue(nas.selectedNfo);assertFalse(nas.selectedSample);}finally{cleanup();}}}
    @Test public void scanningContinuesAtHomeWithScreenOff()throws Exception{try(FakeNas nas=new FakeNas()){try{setup(nas,List.of());for(int n=0;n<40;n++){String folder="/Movies/Movie"+n;nas.folders.add(folder);nas.files.put(folder+"/Movie"+n+".2020.mkv",new byte[]{1,2,3});}nas.listDelayMillis=250;click("refresh_button");long start=System.currentTimeMillis()+10000;while(!app.scanRunning&&System.currentTimeMillis()<start)Thread.sleep(25);assertTrue(app.scanRunning);device.executeShellCommand("input keyevent KEYCODE_HOME");device.executeShellCommand("input keyevent KEYCODE_SLEEP");Thread.sleep(1500);assertFalse("Screen must be off during the scan",device.isScreenOn());assertTrue("Scan service must still run after screen off",app.scanRunning);long end=System.currentTimeMillis()+45000;while(app.scanRunning&&System.currentTimeMillis()<end)Thread.sleep(100);assertFalse("Background scan must finish",app.scanRunning);int[] count={0};instrumentation.runOnMainSync(()->count[0]=app.rawCards.size());assertEquals(42,count[0]);assertFalse(app.busy);}finally{cleanup();}}}
    static byte[] join(byte[]...parts)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();for(byte[] part:parts)out.write(part);return out.toByteArray();}
    static byte[] elem(int id,byte[] data)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();int size=id>0xffffff?4:id>0xffff?3:id>0xff?2:1;for(int n=size-1;n>=0;n--)out.write(id>>(8*n));out.write(0x80|data.length);out.write(data);return out.toByteArray();}
    static byte[] track(int n,String lang)throws Exception{return elem(0xae,join(elem(0xd7,new byte[]{(byte)n}),elem(0x83,new byte[]{2}),elem(0x86,"A_AC3".getBytes(java.nio.charset.StandardCharsets.US_ASCII)),elem(0x22b59c,lang.getBytes(java.nio.charset.StandardCharsets.US_ASCII))));}
    @Test public void multilingualMkvShowsLanguageThenUnrestrictedExternalPlayback()throws Exception{try(FakeNas nas=new FakeNas()){android.app.Instrumentation.ActivityMonitor monitor=null;try{String path="/Movies/Multilingual.mkv";nas.files.put(path,join(new byte[]{0x18,0x53,(byte)0x80,0x67,(byte)0xff},elem(0x1654ae6b,join(track(1,"hun"),track(2,"eng")))));Library.Card card=new Library.Card(path,"Többnyelvű próba",true);setup(nas,List.of(card));device.executeShellCommand("pm grant "+pkg+" android.permission.POST_NOTIFICATIONS");java.util.concurrent.atomic.AtomicReference<Intent> launched=new java.util.concurrent.atomic.AtomicReference<>();monitor=new android.app.Instrumentation.ActivityMonitor(){@Override public android.app.Instrumentation.ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_VIEW.equals(intent.getAction())){launched.set(new Intent(intent));return new android.app.Instrumentation.ActivityResult(android.app.Activity.RESULT_CANCELED,null);}return null;}};instrumentation.addMonitor(monitor);assertTrue(device.wait(Until.hasObject(By.desc(card.title)),10000));device.findObject(By.desc(card.title)).click();click("play_button");assertTrue(device.wait(Until.hasObject(By.text("Szám 1: hun (ac3)")),15000));assertNotNull(device.findObject(By.text("Szám 2: eng (ac3)")));text("Szám 1: hun (ac3)");long deadline=System.currentTimeMillis()+10000;while(launched.get()==null&&System.currentTimeMillis()<deadline)Thread.sleep(25);Intent view=launched.get();assertNotNull(view);assertNull(view.getComponent());assertNull(view.getPackage());assertEquals(StreamService.mime(path),view.getType());assertNotNull(StreamService.readyUri);assertFalse(StreamService.audioPatch.isEmpty());assertFalse(device.hasObject(By.text("Lejátszó kiválasztása")));}finally{if(monitor!=null)instrumentation.removeMonitor(monitor);cleanup();}}}

}
